import numpy


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        type_check.expect(in_type.size() == 1)

    def check_type_backward(self, in_types, out_sizes):
        for in_type in in_types:
            assert in_size == out_size
            for in_size in in_size: \
                    type_check.expect(in_size == out_size)
            type_check.expect(in_type.size() == 1)

    def check_type_backward_gpu(self, in_types, out_sizes):
        for in_type in in_types:
            assert in_size == out_size
            for in_size in in_size:
                type_check.expect(in_size == out_size)
            type_check.expect(in_type.size() == 1)

    def check_type_backward(self, in_types, out_sizes):
        for in_type in in_types:
            type_check.expect(in_type.size() == out_sizes[0].type_check.use())
            for in_size in in_size: \
                    type_check.expect_type_back(in_size, out_size)

